import { useCallback, useEffect, useRef, useState } from "react";

import { classifyTerminalTitleActivity, parseAgentTitle } from "../lib/agentTitle";
import { defaultNotificationCoordinator } from "../lib/notificationCoordinator";
import { terminalHostManager, type TerminalInstance } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { QuickCommandDock } from "./QuickCommandDock";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

function fitMountedTerminal(container: HTMLDivElement, instance: TerminalInstance) {
  if (!container.isConnected || !container.contains(instance.element)) return false;
  const rect = container.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return false;

  Object.assign(instance.element.style, {
    position: "absolute",
    inset: "0px",
    width: "100%",
    height: "100%",
    minWidth: "0px",
    minHeight: "0px",
    overflow: "hidden",
  });
  instance.fitAddon.fit();
  return true;
}

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const latestTitleRef = useRef<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  const handleBell = useCallback(() => {
    onBell?.();
    defaultNotificationCoordinator.handleTerminalBell({
      sessionId: session.id,
      worktreePath: session.worktreePath ?? session.cwd,
      worktreeLabel: session.worktree?.slug,
      terminalTitle: latestTitleRef.current,
    });
  }, [onBell, session.cwd, session.id, session.worktree?.slug, session.worktreePath]);

  const handleTitleChange = useCallback((title: string) => {
    latestTitleRef.current = title;
    onTitleChange?.(title);

    const parsed = parseAgentTitle(title);
    const activity = classifyTerminalTitleActivity(title);
    if (!parsed?.isAgent || !activity) return;

    defaultNotificationCoordinator.handleAgentStateChange({
      sessionId: session.id,
      worktreePath: session.worktreePath ?? session.cwd,
      worktreeLabel: session.worktree?.slug,
      agentLabel: parsed.name,
      terminalTitle: title,
      nextState: activity,
    });
  }, [onTitleChange, session.cwd, session.id, session.worktree?.slug, session.worktreePath]);

  useEffect(() => {
    terminalHostManager.applySettings(settings);
  }, [settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;
    let firstFitFrame = 0;
    let secondFitFrame = 0;
    let resizeObserver: ResizeObserver | null = null;
    setError(null);

    const cancelScheduledFit = () => {
      if (firstFitFrame) cancelAnimationFrame(firstFitFrame);
      if (secondFitFrame) cancelAnimationFrame(secondFitFrame);
      firstFitFrame = 0;
      secondFitFrame = 0;
    };

    const scheduleStableFit = (instance: TerminalInstance, focus = false) => {
      cancelScheduledFit();
      firstFitFrame = requestAnimationFrame(() => {
        firstFitFrame = 0;
        if (cancelled) return;
        const fitted = fitMountedTerminal(container, instance);
        if (focus && fitted) instance.terminal.focus();
        secondFitFrame = requestAnimationFrame(() => {
          secondFitFrame = 0;
          if (cancelled) return;
          fitMountedTerminal(container, instance);
        });
      });
    };

    void terminalHostManager
      .getOrCreate(session, active, handleBell, handleTitleChange, container)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }

        resizeObserver = new ResizeObserver(() => scheduleStableFit(instance));
        resizeObserver.observe(container);
        scheduleStableFit(instance, active);

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled) scheduleStableFit(instance);
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
      resizeObserver?.disconnect();
      cancelScheduledFit();
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    const container = containerRef.current;
    if (instance) {
      instance.active = active;
      instance.onBell = handleBell;
      instance.onTitleChange = handleTitleChange;
      if (active && container) {
        requestAnimationFrame(() => {
          if (fitMountedTerminal(container, instance)) instance.terminal.focus();
        });
      }
    }
  }, [active, handleBell, handleTitleChange, session.id]);

  return (
    <div className="relative h-full w-full min-h-0 min-w-0 overflow-hidden bg-terminal">
      <div ref={containerRef} data-testid="terminal-mount" className="relative h-full w-full min-h-0 min-w-0 overflow-hidden" />
      <QuickCommandDock session={session} active={active} />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

export const PROJECTS_STORAGE_KEY = "ferryx.projects";
export const ACTIVE_PROJECT_STORAGE_KEY = "ferryx.active-project";
export const SIDEBAR_OPEN_STORAGE_KEY = "ferryx.sidebar.open";
export const SIDEBAR_WIDTH_STORAGE_KEY = "ferryx.sidebar.width";
export const SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY = "ferryx.sidebar.collapsedProjects";
export const TERMINAL_SETTINGS_STORAGE_KEY = "ferryx.terminal.settings";
export const NOTIFICATION_SETTINGS_STORAGE_KEY = "ferryx.settings.notifications:v1";
export const APPEARANCE_SETTINGS_STORAGE_KEY = "ferryx.settings.appearance";
export const QUICK_COMMANDS_STORAGE_KEY = "ferryx.settings.quickCommands";
export const BROWSER_SETTINGS_STORAGE_KEY = "ferryx.settings.browser";

export const LEGACY_STORAGE_KEY_MAP: Record<string, string[]> = {
  [PROJECTS_STORAGE_KEY]: ["rorca.projects", "orca.projects"],
  [ACTIVE_PROJECT_STORAGE_KEY]: ["rorca.active-project", "orca.active-project"],
  [SIDEBAR_OPEN_STORAGE_KEY]: ["orca.sidebar.open", "rorca.sidebar.open"],
  [SIDEBAR_WIDTH_STORAGE_KEY]: ["orca.sidebar.width", "rorca.sidebar.width"],
  [SIDEBAR_COLLAPSED_PROJECTS_STORAGE_KEY]: ["rorca.sidebar.collapsedProjects", "orca.sidebar.collapsedProjects"],
  [TERMINAL_SETTINGS_STORAGE_KEY]: ["orca.terminal.settings", "rorca.terminal.settings"],
  [NOTIFICATION_SETTINGS_STORAGE_KEY]: ["rorca:settings:notifications:v1", "orca:settings:notifications:v1"],
};

export function getMigratedItem(
  key: string,
  storage: Pick<Storage, "getItem" | "setItem"> | null = typeof window !== "undefined" && window.localStorage ? window.localStorage : null,
): string | null {
  if (!storage) return null;
  const value = storage.getItem(key);
  if (value !== null) return value;

  const legacyKeys = LEGACY_STORAGE_KEY_MAP[key] ?? [];
  for (const legacyKey of legacyKeys) {
    const legacyVal = storage.getItem(legacyKey);
    if (legacyVal !== null) {
      try {
        storage.setItem(key, legacyVal);
      } catch {
        // ignore quota or disabled storage error
      }
      return legacyVal;
    }
  }
  return null;
}

import {
  applyAppearanceSettings,
  loadAppearanceSettings,
  saveAppearanceSettings,
  type AppearanceSettingsState,
} from "./appearanceSettings";
import { listBrowsers, setBrowserZoom } from "./browserTauri";
import { loadBrowserSettings, saveBrowserSettings } from "./browserSettings";
import { loadQuickCommands, saveQuickCommands } from "./quickCommands";
import { loadTerminalSettings } from "./terminalSettings";

let installed = false;

function findSettingValue(label: string): HTMLElement | null {
  const labels = Array.from(document.querySelectorAll<HTMLElement>("div"));
  const heading = labels.find((element) => element.textContent?.trim() === label);
  const row = heading?.parentElement?.parentElement;
  if (!row) return null;
  const valueContainer = row.lastElementChild;
  return valueContainer?.querySelector<HTMLElement>("span") ?? null;
}

function syncGeneralAppearanceLabels(settings: AppearanceSettingsState) {
  const themeLabel = settings.theme === "system"
    ? "System"
    : settings.theme === "charcoal"
      ? "Charcoal"
      : settings.theme[0].toUpperCase() + settings.theme.slice(1);
  const densityLabel = settings.density === "comfortable" ? "Comfortable" : "Compact";
  const colorValue = findSettingValue("Color scheme");
  const densityValue = findSettingValue("Density");
  if (colorValue && colorValue.textContent !== themeLabel) colorValue.textContent = themeLabel;
  if (densityValue && densityValue.textContent !== densityLabel) densityValue.textContent = densityLabel;
}

function syncTerminalSourceLabel() {
  const settings = loadTerminalSettings();
  const hasLocalOverride = settings.fontFamily !== null || settings.macosOptionAsAlt !== null || settings.fontSize !== null;
  if (!hasLocalOverride) return;

  const headings = Array.from(document.querySelectorAll<HTMLElement>("h2"));
  const heading = headings.find((element) => element.textContent?.trim() === "Effective preferences");
  const source = heading?.nextElementSibling as HTMLElement | null;
  if (source && source.textContent !== "Local override") source.textContent = "Local override";
}

function syncAppearance() {
  const settings = saveAppearanceSettings(loadAppearanceSettings());
  applyAppearanceSettings(settings);
  syncGeneralAppearanceLabels(settings);
}

function syncQuickCommands() {
  saveQuickCommands(loadQuickCommands());
}

function syncBrowser() {
  saveBrowserSettings(loadBrowserSettings());
}

function afterReactEvent(callback: () => void) {
  window.setTimeout(callback, 0);
}

function isInsideSettingsSection(target: EventTarget | null, controlSelector: string) {
  if (!(target instanceof Element)) return false;
  const section = target.closest("section");
  return Boolean(section?.querySelector(controlSelector));
}

async function applyBrowserDefaultZoom() {
  const settings = loadBrowserSettings();
  try {
    const browsers = await listBrowsers();
    await Promise.all(browsers.map((browser) => setBrowserZoom(browser.browserId, settings.defaultZoom / 100)));
  } catch {
    // Browser runtime may not be available in web-preview mode.
  }
}

export function installSettingsRuntimeBridge() {
  if (installed || typeof window === "undefined" || typeof document === "undefined") return;
  installed = true;

  syncAppearance();

  const media = typeof window.matchMedia === "function" ? window.matchMedia("(prefers-color-scheme: light)") : null;
  const handleSystemThemeChange = () => {
    if (loadAppearanceSettings().theme === "system") syncAppearance();
  };
  media?.addEventListener?.("change", handleSystemThemeChange);

  window.addEventListener("change", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLInputElement || target instanceof HTMLSelectElement)) return;

    if (["appearance-theme-mode", "appearance-accent-color", "appearance-density"].includes(target.id)) {
      afterReactEvent(syncAppearance);
      return;
    }
    if (target.id === "quick-commands-enabled") {
      afterReactEvent(syncQuickCommands);
      return;
    }
    if (["browser-search-engine", "browser-default-zoom", "browser-restore-tabs"].includes(target.id)) {
      afterReactEvent(() => {
        syncBrowser();
        if (target.id === "browser-default-zoom") void applyBrowserDefaultZoom();
      });
      return;
    }
    if (["terminal-font-family", "terminal-font-size", "terminal-scrollback"].includes(target.id)) {
      afterReactEvent(syncTerminalSourceLabel);
    }
  }, true);

  window.addEventListener("submit", (event) => {
    const form = event.target;
    if (form instanceof HTMLFormElement && form.querySelector("#qc-new-cmd")) {
      afterReactEvent(syncQuickCommands);
    }
  }, true);

  window.addEventListener("orca:terminal-settings", () => afterReactEvent(syncTerminalSourceLabel));

  window.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const button = target.closest("button");
    if (!button) return;
    const text = button.textContent?.trim() ?? "";

    if (button.getAttribute("aria-label")?.startsWith("Delete command ")) {
      afterReactEvent(syncQuickCommands);
      return;
    }

    if (text === "Reset to defaults") {
      if (isInsideSettingsSection(button, "#appearance-theme-mode")) {
        afterReactEvent(syncAppearance);
      } else if (isInsideSettingsSection(button, "#browser-search-engine")) {
        afterReactEvent(() => {
          syncBrowser();
          void applyBrowserDefaultZoom();
        });
      }
    }
  }, true);

  const observer = new MutationObserver(() => {
    syncGeneralAppearanceLabels(loadAppearanceSettings());
    syncTerminalSourceLabel();
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
}

